def retrieval_source_license_violations(sources: list[dict[str, object]]) -> tuple[str, ...]:
    if not sources:
        return ("at_least_one_source_is_required",)
    violations: list[str] = []
    seen_ids: set[str] = set()
    for index, source in enumerate(sources):
        source_id = source.get("source_id")
        if not isinstance(source_id, str) or not source_id.strip():
            violations.append(f"source_{index}:source_id_is_required")
        elif source_id in seen_ids:
            violations.append(f"source_{index}:source_id_must_be_unique")
        seen_ids.add(source_id)
        if source.get("license") not in _ALLOWED_LICENSES:
            violations.append(f"source_{index}:license_is_not_allowed")
        if source.get("ingestion_permitted") is not True:
            violations.append(f"source_{index}:ingestion_permission_is_required")
        if not isinstance(source.get("owner"), str) or not source["owner"].strip():
            violations.append(f"source_{index}:owner_is_required")
    return tuple(violations)


def retrieval_source_license_is_safe(sources: list[dict[str, object]]) -> bool:
    return not retrieval_source_license_violations(sources)

from __future__ import annotations

from datetime import datetime


def _timestamp(value: object) -> datetime | None:
    if not isinstance(value, str):
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed if parsed.tzinfo is not None and parsed.utcoffset() is not None else None


def evaluation_dataset_provenance_violations(cases: list[dict[str, object]], *, now: datetime, maximum_review_age_days: int = 180) -> tuple[str, ...]:
    if now.tzinfo is None or now.utcoffset() is None:
        raise ValueError("current time must be timezone-aware")
    if not isinstance(maximum_review_age_days, int) or isinstance(maximum_review_age_days, bool) or maximum_review_age_days <= 0:
        raise ValueError("maximum review age must be positive")
    if not cases:
        return ("at_least_one_evaluation_case_is_required",)

    violations: list[str] = []
    seen_case_ids: set[str] = set()
    for index, case in enumerate(cases):
        case_id = case.get("case_id")
        if not isinstance(case_id, str) or not case_id.strip():
            violations.append(f"case_{index}:case_id_is_required")
        elif case_id in seen_case_ids:
            violations.append(f"case_{index}:case_id_must_be_unique")
        seen_case_ids.add(case_id)
        if not isinstance(case.get("source_snapshot"), str) or not case["source_snapshot"].strip():
            violations.append(f"case_{index}:source_snapshot_is_required")
        if not isinstance(case.get("expected_answer"), str) or not case["expected_answer"].strip():
            violations.append(f"case_{index}:expected_answer_is_required")
        source_ids = case.get("source_ids")
        if not isinstance(source_ids, list) or not source_ids or not all(isinstance(source_id, str) and source_id.strip() for source_id in source_ids) or len(set(source_ids)) != len(source_ids):
            violations.append(f"case_{index}:source_ids_must_be_a_unique_non_empty_string_list")
        reviewed_at = _timestamp(case.get("reviewed_at"))
        if reviewed_at is None or (now - reviewed_at).total_seconds() < 0 or (now - reviewed_at).days > maximum_review_age_days:
            violations.append(f"case_{index}:review_is_not_within_age_budget")
    return tuple(violations)


def evaluation_dataset_provenance_is_complete(cases: list[dict[str, object]], **policy: object) -> bool:
    return not evaluation_dataset_provenance_violations(cases, **policy)

from __future__ import annotations

from datetime import datetime
from hashlib import sha256

from scripts.prompt_redaction_check import detected_sensitive_fields


def _timestamp(value: object) -> datetime | None:
    if not isinstance(value, str):
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed if parsed.tzinfo is not None and parsed.utcoffset() is not None else None


def response_pii_redaction_violations(response: str, report: dict[str, object], *, now: datetime, maximum_age_seconds: int = 900) -> tuple[str, ...]:
    if not isinstance(response, str):
        raise ValueError("response must be a string")
    if now.tzinfo is None or now.utcoffset() is None:
        raise ValueError("current time must be timezone-aware")
    if not isinstance(maximum_age_seconds, int) or isinstance(maximum_age_seconds, bool) or maximum_age_seconds <= 0:
        raise ValueError("maximum report age must be a positive integer")

    violations: list[str] = []
    expected_digest = sha256(response.encode("utf-8")).hexdigest()
    if report.get("response_sha256") != expected_digest:
        violations.append("response_digest_must_match_content")
    if not isinstance(report.get("detector_version"), str) or not report["detector_version"].strip():
        violations.append("detector_version_is_required")

    scanned_at = _timestamp(report.get("scanned_at"))
    if scanned_at is None:
        violations.append("scanned_at_must_be_timezone_aware")
    else:
        age = (now - scanned_at).total_seconds()
        if age < 0:
            violations.append("scan_time_is_in_the_future")
        elif age > maximum_age_seconds:
            violations.append("scan_is_stale")

    detected = detected_sensitive_fields(response)
    reported_categories = report.get("detected_categories")
    if not isinstance(reported_categories, list) or not all(isinstance(item, str) and item.strip() for item in reported_categories):
        violations.append("detected_categories_must_be_a_string_list")
    elif set(reported_categories) != set(detected):
        violations.append("detected_categories_must_match_response")
    if detected:
        violations.append("response_contains_sensitive_data")
        if report.get("release_decision") != "blocked":
            violations.append("sensitive_response_must_be_blocked")
    elif report.get("release_decision") != "allowed":
        violations.append("clean_response_must_be_explicitly_allowed")
    return tuple(violations)


def response_is_safe_to_release(response: str, report: dict[str, object], **policy: object) -> bool:
    return not response_pii_redaction_violations(response, report, **policy)

from __future__ import annotations


_ALLOWED = {"safe", "review", "blocked"}


def response_safety_classification_violations(records: list[dict[str, object]], *, minimum_safe_confidence: float = 0.8) -> tuple[str, ...]:
    if not isinstance(minimum_safe_confidence, (int, float)) or isinstance(minimum_safe_confidence, bool) or not 0 < minimum_safe_confidence <= 1:
        raise ValueError("minimum safe confidence must be between zero and one")
    if not records:
        return ("at_least_one_response_record_is_required",)
    violations: list[str] = []
    seen_ids: set[str] = set()
    for index, record in enumerate(records):
        response_id = record.get("response_id")
        if not isinstance(response_id, str) or not response_id.strip():
            violations.append(f"record_{index}:response_id_is_required")
        elif response_id in seen_ids:
            violations.append(f"record_{index}:response_id_must_be_unique")
        seen_ids.add(response_id)
        classification = record.get("classification")
        if classification not in _ALLOWED:
            violations.append(f"record_{index}:classification_is_invalid")
        confidence = record.get("confidence")
        if not isinstance(confidence, (int, float)) or isinstance(confidence, bool) or not 0 <= confidence <= 1:
            violations.append(f"record_{index}:confidence_must_be_between_zero_and_one")
        elif classification == "safe" and confidence < minimum_safe_confidence:
            violations.append(f"record_{index}:safe_classification_confidence_is_too_low")
        if record.get("release") is not (classification == "safe"):
            violations.append(f"record_{index}:release_decision_must_match_classification")
    return tuple(violations)


def response_safety_classification_is_safe(records: list[dict[str, object]], **policy: object) -> bool:
    return not response_safety_classification_violations(records, **policy)

from __future__ import annotations


def vector_index_capacity_violations(observations: list[dict[str, object]], *, maximum_utilization: float = 0.85) -> tuple[str, ...]:
    if not isinstance(maximum_utilization, (int, float)) or isinstance(maximum_utilization, bool) or not 0 < maximum_utilization <= 1:
        raise ValueError("maximum utilization must be between zero and one")
    if not observations:
        return ("at_least_one_collection_observation_is_required",)
    violations: list[str] = []
    seen_names: set[str] = set()
    for index, observation in enumerate(observations):
        name = observation.get("collection")
        if not isinstance(name, str) or not name.strip():
            violations.append(f"collection_{index}:name_is_required")
        elif name in seen_names:
            violations.append(f"collection_{index}:name_must_be_unique")
        seen_names.add(name)
        vectors, capacity = observation.get("vector_count"), observation.get("capacity")
        if not isinstance(vectors, int) or isinstance(vectors, bool) or vectors < 0:
            violations.append(f"collection_{index}:vector_count_must_be_non_negative")
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity <= 0:
            violations.append(f"collection_{index}:capacity_must_be_positive")
        elif isinstance(vectors, int) and not isinstance(vectors, bool) and vectors / capacity > maximum_utilization:
            violations.append(f"collection_{index}:utilization_exceeds_budget")
        shards = observation.get("shard_count")
        if not isinstance(shards, int) or isinstance(shards, bool) or shards <= 0:
            violations.append(f"collection_{index}:shard_count_must_be_positive")
    return tuple(violations)


def vector_index_capacity_is_safe(observations: list[dict[str, object]], **policy: object) -> bool:
    return not vector_index_capacity_violations(observations, **policy)

from __future__ import annotations

from datetime import datetime
import re


_SHA256 = re.compile(r"[0-9a-f]{64}\Z")


def _timestamp(value: object) -> datetime | None:
    if not isinstance(value, str):
        return None
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed if parsed.tzinfo is not None and parsed.utcoffset() is not None else None


def retrieval_indexing_freshness_violations(records: list[dict[str, object]], *, now: datetime, maximum_delay_hours: int = 24) -> tuple[str, ...]:
    if now.tzinfo is None or now.utcoffset() is None:
        raise ValueError("current time must be timezone-aware")
    if not isinstance(maximum_delay_hours, int) or isinstance(maximum_delay_hours, bool) or maximum_delay_hours <= 0:
        raise ValueError("maximum delay hours must be positive")
    if not records:
        return ("at_least_one_indexing_record_is_required",)
    violations: list[str] = []
    seen_ids: set[str] = set()
    for index, record in enumerate(records):
        source_id = record.get("source_id")
        if not isinstance(source_id, str) or not source_id.strip():
            violations.append(f"record_{index}:source_id_is_required")
        elif source_id in seen_ids:
            violations.append(f"record_{index}:source_id_must_be_unique")
        if isinstance(source_id, str):
            seen_ids.add(source_id)
        if not isinstance(record.get("content_sha256"), str) or not _SHA256.fullmatch(record["content_sha256"]):
            violations.append(f"record_{index}:content_sha256_is_invalid")
        source_updated_at = _timestamp(record.get("source_updated_at"))
        indexed_at = _timestamp(record.get("indexed_at"))
        if source_updated_at is None or indexed_at is None:
            violations.append(f"record_{index}:timestamps_must_be_timezone_aware")
            continue
        delay = (indexed_at - source_updated_at).total_seconds()
        age = (now - indexed_at).total_seconds()
        if delay < 0 or delay > maximum_delay_hours * 3600:
            violations.append(f"record_{index}:indexing_delay_exceeds_budget")
        if age < 0 or age > maximum_delay_hours * 3600:
            violations.append(f"record_{index}:index_observation_is_not_fresh")
    return tuple(violations)


def retrieval_indexing_is_fresh(records: list[dict[str, object]], **policy: object) -> bool:
    return not retrieval_indexing_freshness_violations(records, **policy)

